args.command:
command -v pdftoppm; command -v pdfimages; fc-match 'Noto Sans CJK SC' -f '%{file}
'; fc-match 'Noto Serif CJK SC' -f '%{file}
'; fc-match 'Noto Sans CJK SC:style=Bold' -f '%{file}
'

args.newText:
body > h1:first-child::after {
  content: "从市场判断到 ROA / ROE 的经营闭环\A\A MANAGEMENT SIMULATION\A 2026 · 08";
  white-space: pre-wrap;
  display: block;
  margin-top: 42mm;
  padding-top: 8mm;
  width: 118mm;
  border-top: 1px solid rgba(255,255,255,.3);
  font-family: "Noto Sans CJK SC", sans-serif;
  font-size: 11pt;
  line-height: 2;
  font-weight: 400;
  color: rgba(255,255,255,.78);
  letter-spacing: .05em;
}
body > h1:first-child + blockquote { display: none; }

args.oldText:
body > h1:first-child::after {
  content: "从市场判断到 ROA / ROE 的经营闭环\A\A 2026 · 08";
  white-space: pre-wrap;
  display: block;
  margin-top: 30mm;
  max-width: 110mm;
  font-family: "Noto Sans CJK SC", sans-serif;
  font-size: 12pt;
  line-height: 1.8;
  font-weight: 400;
  color: rgba(255,255,255,.78);
  letter-spacing: .04em;
}
body > h1:first-child + blockquote {
  position: absolute;
  top: 129mm;
  left: 25mm;
  width: 142mm;
  margin: 0;
  padding: 7mm 8mm;
  border: 0;
  border-left: 3px solid #62d4c8;
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.88);
  font-family: "Noto Sans CJK SC", sans-serif;
  font-size: 10pt;
  line-height: 1.9;
}
body > h1:first-child + blockquote p { margin: 0; }
body > h1:first-child + blockquote strong { color: #fff; }

